INSERT INTO catalogue_products (product_name, product_name_telugu, catalogue_category, product_category, descriptor, product_tagline, product_description, ingredients, hero_ingredient_1, hero_ingredient_2, hero_ingredient_3, serving_suggestion, serving_size_g, shelf_life_days, is_veg, contains_nuts, is_jain, is_vegan, webpage_url, nutrition_serving_size, nutrition_calories, nutrition_protein, nutrition_total_fat, nutrition_saturated_fat, nutrition_carbs, nutrition_fiber, nutrition_sugars, nutrition_sodium, price_100g_standup, price_250g_standup, price_500g_pouch, price_1kg_pouch, price_100g_glass_jar, price_one_unit_pouch, photo_standup_pouch, photo_glass_jar, Category_Colour) VALUES ('Palli Kaaram', 'పల్లి కారం', 'Nutty', 'ready-to-eat', 'Peanut Kaaram Podi', 'Palli Kaaram. Boldly Telugu!', 'A nutty and spicy Kadapa classic made with peanuts, chili, and curry leaves. A true part of local culture — delicious with rice or even as a snack on its own.', 'Peanuts, Curry Leaf, Dry Red Chilly, Garlic, Red Chilly Powder, Salt, Cumin', 'Peanuts', 'Garlic', '0', 'Add this unique Rayalaseema blend of roasted peanuts, garlic, and curry leaves to hot rice. Mix in a spoonful of ghee and serve warm!', 5, 90, 'Yes', 'Yes (Peanuts)', 'No (Garlic)', 'Yes', 'https://telugudelicacies.com/ready-to-eat/palli-kaaram', '5g', '25.87kcal', '1.24g', '2.04g', '0.36g', '1.02g', '0.64g', '0.2g', '0.07g', 55.0, 135.0, 255.0, 495.0, 105.0, NULL, 'Palli Kaaram_Standup_Pouch.png', 'Palli Kaaram_Cylindrical_Glass_Jar.png', 'e64456ff');
INSERT INTO catalogue_products (product_name, product_name_telugu, catalogue_category, product_category, descriptor, product_tagline, product_description, ingredients, hero_ingredient_1, hero_ingredient_2, hero_ingredient_3, serving_suggestion, serving_size_g, shelf_life_days, is_veg, contains_nuts, is_jain, is_vegan, webpage_url, nutrition_serving_size, nutrition_calories, nutrition_protein, nutrition_total_fat, nutrition_saturated_fat, nutrition_carbs, nutrition_fiber, nutrition_sugars, nutrition_sodium, price_100g_standup, price_250g_standup, price_500g_pouch, price_1kg_pouch, price_100g_glass_jar, price_one_unit_pouch, photo_standup_pouch, photo_glass_jar, Category_Colour) VALUES ('Special Godhuma Kaaram', 'స్పెషల్ గోధుమ కారం', 'Nutty', 'ready-to-eat', 'Special Nutty Kaaram Podi', 'Tasty, Light & Fresh!', 'A wholesome, nutty podi made with chakki atta, dals, coconut, and garlic. Perfectly balanced, it brings a bold, hearty flavor to your meals.', 'Chakki Atta, Urad Dal, Red Chilly Powder, Dry Coconut, Flax Seed, Garlic, Salt', 'Chakki Atta', 'Dry Coconut', 'Flax Seed', 'Smear this unique, nutty mix of whole wheat, urad dal, and garlic onto dosas, or pair it with melted ghee for the perfect savory idli dip.', 5, 90, 'Yes', 'No', 'No (Garlic Cut)', 'Yes', 'https://telugudelicacies.com/ready-to-eat/special-godhuma-kaaram', '5g', '17.24kcal', '0.68g', '0.41g', '0.2g', '2.93g', '0.76g', '0.09g', '0.07g', 45.0, 110.0, 210.0, 405.0, 95.0, NULL, 'Special Godhuma Kaaram_Standup_Pouch.png', 'Special Godhuma Kaaram_Cylindrical_Glass_Jar.png', 'e64456ff');
INSERT INTO catalogue_products (product_name, product_name_telugu, catalogue_category, product_category, descriptor, product_tagline, product_description, ingredients, hero_ingredient_1, hero_ingredient_2, hero_ingredient_3, serving_suggestion, serving_size_g, shelf_life_days, is_veg, contains_nuts, is_jain, is_vegan, webpage_url, nutrition_serving_size, nutrition_calories, nutrition_protein, nutrition_total_fat, nutrition_saturated_fat, nutrition_carbs, nutrition_fiber, nutrition_sugars, nutrition_sodium, price_100g_standup, price_250g_standup, price_500g_pouch, price_1kg_pouch, price_100g_glass_jar, price_one_unit_pouch, photo_standup_pouch, photo_glass_jar, Category_Colour) VALUES ('Special Palli Kaaram', 'స్పెషల్ పల్లి కారం', 'Nutty', 'ready-to-eat', 'Special Peanut Kaaram Podi', 'Rustic. Rich. Ridiculously Good!', 'Our best-reviewed podi! A rustic blend of peanuts, coriander, and jaggery that delivers mellow, nutty flavors. Smooth and balanced, it’s even loved by kids when mixed with hot rice and ghee.', 'Peanuts, Fried Gram, Coriander, Jaggery, Dry Red Chilly, Salt, Tamarind', 'Peanuts', 'Coriander Seeds', 'Mirchi Dry', 'Toss this flavorful mix of peanuts, fried gram, and coriander with hot rice and a good serving of ghee to beautifully bring out the sweet and tangy notes.', 5, 60, 'Yes', 'Yes (Peanuts)', 'Yes', 'Yes', 'https://telugudelicacies.com/ready-to-eat/special-palli-kaaram', '5g', '19.99kcal', '0.87g', '1.03g', '0.16g', '2.23g', '0.69g', '0.85g', '0.13g', 60.0, 145.0, 280.0, 540.0, 110.0, NULL, 'Special Palli Kaaram_Standup_Pouch.png', 'Special Palli Kaaram_Cylindrical_Glass_Jar.png', 'e64456ff');
